mapper.select:
SELECT c.*, cfg.account_name AS account_name, ct.name AS contact_name, f.nickname AS nickname, f.avatar_url AS avatar_url FROM crm_wechat_mp_article_comment c LEFT JOIN crm_wechat_mp_config cfg ON cfg.app_id = c.app_id LEFT JOIN crm_contact ct ON ct.contact_id = c.contact_id LEFT JOIN crm_wechat_mp_fan f ON f.app_id = c.app_id AND c.openid IS NOT NULL AND c.openid <> '' AND f.open_id = c.openid
AND c.app_id = #{appId}
AND c.app_id IN
#{aid}
AND c.status = #{status}
AND c.msg_data_id = #{msgDataId}
AND c.index_in_msg = #{indexInMsg}
AND ( c.content ILIKE ('%' || #{keyword} || '%') OR c.article_title ILIKE ('%' || #{keyword} || '%') )
ORDER BY c.comment_time DESC
